 b.write(here/'state_event_control.py',"\"\"\"駆動MSDが混在する音素の状態時計を固定し、均質状態だけを再配分する。\"\"\"\nimport numpy as np,re\nfrom timing_control import descriptions,projected,integer_sum,LOWER,UPPER\ndef durations(row,snapshot,predictor):\n duration=np.array(snapshot['duration'],int).reshape(-1,5)\n prob=np.asarray(snapshot['msd'],float)\n if not np.isfinite(prob).all() or np.any(prob<0) or np.any(prob>1):raise ValueError('MSDの有限確率を要求')\n mask=prob.reshape(-1,5)>.5\n length=duration.sum(1)\n if len(length)!=len(row['full_context_labels']) or mask.shape!=duration.shape or np.any(duration<1):\n  raise ValueError('HMM状態時計/有声判定と音素ラベルの不一致')\n r=descriptions(row);indices=[q['label_index'] for q in r]\n if not indices:raise ValueError('発話音素が空')\n value=projected(predictor(np.array([q['x'] for q in r])));assert len(value)==len(indices)\n mixed=np.any(mask,axis=1)&~np.all(mask,axis=1)\n flexible=[i for i in indices if not mixed[i]]\n wanted=length.copy();newduration=duration.copy()\n effective=np.array([y for i,y in zip(indices,value) if not mixed[i]])\n if flexible and np.any(effective):\n  l=length[flexible];low=np.maximum(5,np.ceil(LOWER*l).astype(int));high=np.maximum(low,np.floor(UPPER*l).astype(int))\n  wanted[flexible]=integer_sum(l*np.exp(effective),int(l.sum()),low,high)\n  for i in flexible:\n   if wanted[i]!=length[i]:\n    newduration[i]=integer_sum(duration[i].astype(float),int(wanted[i]),np.ones(5,int),np.full(5,wanted[i]-4,int))\n notes=[]\n for q,y in zip(r,value):\n  i=q['label_index'];notes.append(dict(label_index=i,phone=q['phone'],predicted_log_ratio=float(y),native_frames=int(length[i]),output_frames=int(wanted[i]),mixed_MSD_fixed=bool(mixed[i])))\n assert newduration.sum()==duration.sum() and np.all(newduration>=1)\n for i,q in enumerate(row['full_context_labels']):\n  if mixed[i] or re.search(r'\\-([^+]+)\\+',q)[1] in ['sil','pau']:\n   assert np.array_equal(newduration[i],duration[i])\n if not np.any(value):assert np.array_equal(newduration,duration)\n return newduration.ravel().tolist(),notes\n".encode(),j)
 b.write(here/'prepare.py',"\"\"\"既存モデル・訓練80と、新16確認文章を波形生成前に固定する。\"\"\"\nfrom paths import *\nimport sys,re,unicodedata\nsys.path[:0]=[str(BUNDLE),str(SHARED)]\nfrom japanese_frontend import analyze\nimport pyopenjtalk\ndef norm(s):return re.sub(r'[\\W_]','',unicodedata.normalize('NFKC',s))\ndef collect(v,texts,labels):\n if isinstance(v,dict):\n  if isinstance(v.get('text'),str):texts.add(norm(v['text']))\n  if v.get('full_context_labels'):labels.add(tuple(v['full_context_labels']))\n  for x in v.values():collect(x,texts,labels)\n elif isinstance(v,list):\n  for x in v:collect(x,texts,labels)\ndef main():\n b=Budget();reg=read(HERE/'registration.json')\n with b.job(NAME,'setup','混在state長保護の訓練履歴96分母と新確認16を固定',reserve_bytes=18000000) as j:\n  previous=read(TIME/'protocol.json');target=read(COVERAGE/'target-manifest.json');used={r['id'] for r in target['rows'] if r['status']=='accepted'};train=[dict(r) for r in previous['training_rows'] if r['id'] in used];assert len(train)==80\n  failed=[dict(id=r['id'],text=r['text'],reason=r['reason']) for r in target['rows'] if r['status']!='accepted'];assert len(failed)==16\n  seen=read(COVERAGE/'novelty-audit.json')['history_reference_hashes'];texts=set();labels=set();history=dict(seen)\n  for n,h in seen.items():\n   assert not re.search('splits|protected|holdout|final-confirm',n,re.I);assert digest(REPO/n)==h;collect(read(REPO/n),texts,labels)\n  for directory in [COVERAGE,TIME]:\n   for filename in ['protocol.json','novelty-audit.json']:\n    path=directory/filename;collect(read(path),texts,labels);history[str(path.relative_to(REPO))]=digest(path)\n  rows=[]\n  for length in ['short','long']:\n   for group,source in enumerate(sorted([r for r in read(JP/'protocol.json')['rows'] if r['length']==length],key=lambda r:r['id'])[:4]):\n    r=analyze(source['text']);assert r['full_context_labels']==source['full_context_labels'];r.update(id=source['id'],cohort='legacy_diagnostic',length=length,challenge_group=group);rows.append(r)\n  fresh=[];pool=[]\n  for length in ['short','long']:\n   chosen=[]\n   for text in reg['candidate_pool_'+length]:\n    r=analyze(text);collision=norm(text) in texts or tuple(r['full_context_labels']) in labels;valid=3<=len(r['full_context_labels'])<=122;select=not collision and valid and len(chosen)<8;pool.append(dict(text=text,length=length,collision=collision,label_count=len(r['full_context_labels']),valid_label_count=valid,selected=select))\n    if select:chosen.append(r);texts.add(norm(text));labels.add(tuple(r['full_context_labels']))\n   assert len(chosen)==8,'混在state長保護用新入力が不足：fit/生成前停止'\n   for group,r in enumerate(chosen):r.update(id='event-fresh-'+str(len(fresh)).zfill(2),cohort='prospective_once',length=length,challenge_group=group);fresh.append(r)\n  rows+=fresh\n  for r in train:r.update(cohort='training_diagnostic',requests={'neutral':{'requested_f0':220.,'speed':1.}},kana=pyopenjtalk.g2p(r['text'],kana=True))\n  for r in rows:r.update(requests={'neutral':{'requested_f0':220.,'speed':1.},'higher':{'requested_f0':280.,'speed':1.15}},kana=pyopenjtalk.g2p(r['text'],kana=True))\n  dependencies=dict(previous['dependencies']);dependencies[str((TIME/'artifact-seal.json').relative_to(REPO))]=digest(TIME/'artifact-seal.json')\n  b.save(HERE/'novelty-audit.json',dict(history_reference_hashes=history,pool_checked_before_output=pool,selected_rows=[dict(id=r['id'],text=r['text'],kana=r['kana']) for r in fresh],protected_confirmation_opened=False,final_quality_independence_claim=False),j)\n  b.save(HERE/'protocol.json',dict(registration_sha256=digest(HERE/'registration.json'),rows=rows,training_rows=train,excluded_prior_training=failed,original_training_denominator=96,variants=reg['variants'],training_variants=reg['variants'],conditions=['neutral','higher'],dependencies=dependencies,diagnostic_records=336,training_records=560,reused_training_renders=320,new_training_renders=240,new_diagnostic_renders=336,training_ASR_not_independent_quality=True,no_optimization_after_ASR=True,teacher_available_at_unknown_generation=False,quality_certified=False),j)\n  b.save(HERE/'engine-contract.json',read(TIME/'engine-contract.json'),j)\n print('混在state長保護入力固定',len(train),len(fresh),flush=True);print(b.reconcile(),flush=True)\nif __name__=='__main__':main()\n".encode(),j)
 b.write(here/'self-test.py',"\"\"\"旧ゼロ制御と混在state長固定を、実HMMと波形で検査する。\"\"\"\nfrom paths import *\nimport sys,math,hashlib,numpy as np\nSRC=ROOT/'campaigns/nas-source-identity-20261004-v1'\nsys.path[:0]=[str(HERE),str(SRC),str(WORLD),str(SHARED),str(BUNDLE)]\nfrom timing_engine import Engine\nfrom timing_control import durations as original,FEATURES,LOGBOUND\nfrom state_event_control import durations as mixed_fixed\nfrom world_renderer2 import synthesize\nfrom teacher_common import wavbytes\nfrom acoustics import evaluate\ndef ah(x):return hashlib.sha256(np.asarray(x,dtype='<f8').tobytes()).hexdigest()\ndef main():\n b=Budget();old=read(TIME/'protocol.json');row=next(r for r in old['rows'] if r['id']=='timing-fresh-00');pairs=[]\n for condition,request in row['requests'].items():\n  expected=read(TIME/'render/diagnostic'/row['id']/condition/'native.json')\n  values=[]\n  for mode in ['native','original_zero','mixed_zero']:\n   with b.job(NAME,'render','新policyゼロ自己回復 '+condition+'/'+mode,reserve_bytes=4000000) as j:\n    with Engine(row,BUNDLE/'mei_normal.htsvoice',speed=request['speed'],half_tone=12*math.log2(request['requested_f0']/220)) as e:\n     before=e.snapshot();v=e.variance();settings=e.get_settings()\n     if mode!='native':\n      fun=original if mode=='original_zero' else mixed_fixed\n      d,n=fun(row,before,lambda x:np.zeros(len(x)));assert d==before['duration'];_,after=e.modify_duration(d);assert before==after\n     params=e.parameters();raw,_=synthesize(params,settings);assert e.snapshot()==before and np.array_equal(v,e.variance())\n    audio=(raw*.25).astype(np.float32)\n    with b.job(NAME,'dsp','ゼロfixture E0 '+condition+'/'+mode,reserve_bytes=1000):\n     assert evaluate(audio,{},24000)['E0_pass']\n    path=HERE/'self-test'/condition/(mode+'.wav');b.write(path,wavbytes(audio),j)\n    value=dict(wav_sha256=digest(path),parameter_hashes=[ah(q) for q in params],duration=before['duration'])\n    assert value['wav_sha256']==expected['wav_sha256'] and value['parameter_hashes']==expected['parameter_hashes'] and value['duration']==expected['duration']\n    b.save(path.with_suffix('.json'),value,j);values.append(value)\n  assert values[0]==values[1]==values[2];pairs.append(dict(condition=condition,original_mixed_zero_bit_match=True))\n with b.job(NAME,'setup','MSD混在の状態長固定と、元policyへの同値/差分を検査',reserve_bytes=20000) as j:\n  with Engine(row,BUNDLE/'mei_normal.htsvoice',speed=1.,half_tone=0.) as e:\n   before=e.snapshot();v=e.variance();base=np.array(before['duration']).reshape(-1,5);mask=np.array(before['msd']).reshape(-1,5)>.5;mix=np.any(mask,axis=1)&~np.all(mask,axis=1);assert mix.any()\n   f=lambda x:np.linspace(-LOGBOUND,LOGBOUND,len(x))\n   d,n=mixed_fixed(row,before,f);arr=np.array(d).reshape(-1,5)\n   assert np.array_equal(arr[mix],base[mix]) and sum(d)==sum(before['duration']) and np.all(arr>=1)\n   _,after=e.modify_duration(d);assert np.array_equal(v,e.variance()) and all(before[k]==after[k] for k in ['means','msd','layout'])\n   e.parameters();assert e.snapshot()==after and np.array_equal(v,e.variance())\n  bad=dict(before,msd=[float('nan')]*len(before['msd']))\n  try:mixed_fixed(row,bad,f)\n  except ValueError:pass\n  else:raise AssertionError('非有限MSDを拒否')\n  uniform=dict(before,msd=[1.]*len(before['msd']));assert original(row,uniform,f)[0]==mixed_fixed(row,uniform,f)[0]\n  uniform=dict(before,msd=[0.]*len(before['msd']));assert original(row,uniform,f)[0]==mixed_fixed(row,uniform,f)[0]\n  b.save(HERE/'self-test.json',dict(passed=True,pairs=pairs,render_calls=6,E0_calls=6,mixed_state_durations_exactly_native=True,total_frame_count_preserved=True,means_variance_MSD_layout_preserved=True,uniform_voicing_matches_original_projection=True,nonfinite_MSD_rejected=True,current_source_sha256=digest(HERE/'state_event_control.py'),inherited_C_validation_sha256=digest(TIME/'self-test.json'),fixture_not_quality_evidence=True),j)\n print('mixed-state policy自己回復・構造不変を通過',flush=True);print(b.reconcile(),flush=True)\nif __name__=='__main__':main()\n".encode(),j)
